// seed: tests/seed.admin.spec.ts
// ПРОД: только просмотр. Внутри экрана молитвы НИЧЕГО не нажимать (שמירת טיוטה / אישור ופרסום / אישור כל התפילה /
// העלאת קובץ MP3 / עריכת ההסבר והטיפ / הוספת קטע) — утверждение необратимо, загрузка видна всем.
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

test.describe('Админка контента молитв (/admin)', () => {
  test('AD-04 Экран молитвы в админке: карточки объяснения, MP3, «אישור כל התפילה», קטעים, «הוספת קטע», история #a5decf4a @prod-safe @mobile', async ({ page }) => {
    // 1. /admin → карточка «ערבית · נוסח אשכנז».
    await page.goto('/admin');
    await expect(page.getByText('ניהול תכני תפילה')).toBeVisible({ timeout: 20_000 });
    await page.getByText(/^ערבית\s*.\s*נוסח אשכנז$/).first().click();

    await expect(page.getByText('קטעי התפילה', { exact: true })).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText(/^ערבית\s*.\s*נוסח אשכנז$/).first()).toBeVisible();
    await expect(page.getByText(/^\d+ מתוך 15 קטעים מאושרים$/)).toBeVisible();

    // Карточки экрана молитвы.
    await expect(page.getByText('הסבר וטיפ על התפילה', { exact: true })).toBeVisible();
    await expect(page.getByRole('button', { name: 'עריכת ההסבר והטיפ' })).toBeVisible();
    await expect(page.getByText('הקלטת התפילה (MP3)', { exact: true })).toBeVisible();
    await expect(page.getByText('אישור כל התפילה', { exact: true }).first()).toBeVisible();
    await expect(page.getByRole('button', { name: 'הוספת קטע' })).toBeVisible();
    await expect(page.getByText('היסטוריית אישורים', { exact: true })).toBeVisible();

    // קטע 3 «המעריב ערבים» — «מאושר · <имя>, <дата>»; хотя бы один фрагмент ещё «טקסט זמני, טרם אושר».
    await expect
      .poll(async () => (await page.locator('body').innerText()).match(/המעריב ערבים[\s\S]{0,60}?מאושר\s*.\s*[^\n,]+,\s*\d{1,2}\.\d{1,2}\.\d{4}/) !== null)
      .toBe(true);
    await expect(page.getByText('טקסט זמני, טרם אושר', { exact: true }).first()).toBeVisible();

    // История: запись про «המעריב ערבים» с «אושר על ידי» (формулировку «נוסח חדש אושר» не сверять — баг #cdbc90a6).
    await expect(page.getByText(/^המעריב ערבים: .*אושר על ידי /).first()).toBeVisible();
  });
});
